<?php
$low=db()->query("SELECT p.*,b.name brand_name,c.name category_name FROM products p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN categories c ON c.id=p.category_id WHERE p.is_active=1 AND p.stock<=p.critical_stock ORDER BY p.stock ASC,p.name LIMIT 100")->fetchAll();
$moves=db()->query("SELECT m.*,p.name product_name,p.sku,a.username admin_name FROM stock_movements m JOIN products p ON p.id=m.product_id LEFT JOIN admins a ON a.id=m.admin_id ORDER BY m.id DESC LIMIT 150")->fetchAll();
?>
<div class="admin-page-head"><div><span class="eyebrow">STOK & TEDARİK</span><h2>Stok Hareketleri</h2><p>Kritik stokları ve satış/satın alma kaynaklı hareketleri izleyin.</p></div><div class="admin-actions"><a class="admin-btn primary" href="?page=purchases">+ Mal Alışı</a></div></div>
<div class="metric-grid metric-grid-4"><div class="metric <?=$low?'danger':''?>"><span class="label">Kritik Stok</span><strong><?=count($low)?></strong><small>Ürün</small></div><div class="metric"><span class="label">Bugünkü Hareket</span><strong><?=(int)db()->query("SELECT COUNT(*) FROM stock_movements WHERE DATE(created_at)=CURDATE()")->fetchColumn()?></strong><small>Satır</small></div><div class="metric"><span class="label">Toplam Stok</span><strong><?=number_format((int)db()->query('SELECT COALESCE(SUM(stock),0) FROM products WHERE is_active=1')->fetchColumn())?></strong><small>Adet</small></div><div class="metric"><span class="label">Stokta Olmayan</span><strong><?=(int)db()->query('SELECT COUNT(*) FROM products WHERE is_active=1 AND stock<=0')->fetchColumn()?></strong><small>Ürün</small></div></div>
<div class="admin-grid-wide"><section class="admin-card"><div class="admin-card-head"><div><h3>Kritik Stok Listesi</h3><p>Stok ≤ kritik stok</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Ürün</th><th>Kategori</th><th>Marka</th><th>Stok</th><th>Kritik</th><th></th></tr></thead><tbody><?php if(!$low):?><tr><td colspan="6"><?=wy_empty('Kritik stok yok','Tüm aktif ürünler güvenli stok seviyesinde.')?></td></tr><?php endif;?><?php foreach($low as $p):?><tr><td><b><?=h($p['name'])?></b><small><?=h($p['sku'])?></small></td><td><?=h($p['category_name'])?></td><td><?=h($p['brand_name'])?></td><td><span class="stock-low"><?=(int)$p['stock']?></span></td><td><?=(int)$p['critical_stock']?></td><td><a class="admin-btn light" href="?page=product_edit&id=<?=(int)$p['id']?>">Ürünü Aç</a></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-card"><div class="admin-card-head"><div><h3>Son Stok Hareketleri</h3><p>Satış, alış ve manuel hareket günlüğü</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Tarih</th><th>Ürün</th><th>Tür</th><th>Adet</th><th>Maliyet</th><th>Referans</th></tr></thead><tbody><?php foreach($moves as $m):?><tr><td><?=h(date('d.m.Y H:i',strtotime($m['created_at'])))?></td><td><b><?=h($m['product_name'])?></b><small><?=h($m['sku'])?></small></td><td><?=h($m['movement_type'])?></td><td><b class="<?=$m['quantity']<0?'stock-low':'stock-ok'?>"><?=$m['quantity']>0?'+':''?><?=(int)$m['quantity']?></b></td><td><?=h($m['unit_cost']!==null?money($m['unit_cost']):'—')?></td><td><?=h(($m['reference_type']?:'').' '.($m['reference_id']?:''))?></td></tr><?php endforeach;?></tbody></table></div></section></div>